package cn.bidcheck.ocr;

import java.util.*;
import org.junit.jupiter.api.Test;
import static cn.bidcheck.ocr.OcrLayout.*;
import static cn.bidcheck.ocr.GridLayoutAssembler.*;
import static org.junit.jupiter.api.Assertions.*;

class GridLayoutAssemblerTest {
    final GridLayoutAssembler assembler=new GridLayoutAssembler();
    final String text="姓名 月份\n合成甲 2025-01";
    final Frame frame=new Frame("f",200,100,"a".repeat(64),"PDF_PAGE",1,null,null,null);
    OcrLayout base(){return new OcrLayout(OcrLayout.VERSION,"COMPLETE",COORDINATES,List.of(frame),List.of(new TextBox("b1","f","姓名",new Box(10,10,30,10),null),new TextBox("b2","f","月份",new Box(110,10,30,10),.8),new TextBox("b3","f","合成甲",new Box(10,60,30,10),.9),new TextBox("b4","f","2025-01",new Box(110,60,70,10),null)),List.of(),List.of("b1","b2","b3","b4"),List.of()).validated(text);}
    Region cell(int row,int col,double x1,double y1,double x2,double y2,boolean header){return new Region(row,col,1,1,List.of(x1,y1,x2,y2),header);}
    Grid grid(){return new Grid("f",PIXEL_XYXY,2,2,List.of(cell(0,0,0,0,100,50,true),cell(0,1,100,0,200,50,true),cell(1,0,0,50,100,100,false),cell(1,1,100,50,200,100,false)));}
    Set<String> codes(Assembly result){return new HashSet<>(result.diagnostics().stream().map(Diagnostic::code).toList());}
    @Test void serverGeneratesTextReferencesHeadersAndStableIds(){var result=assembler.assemble(base(),text,List.of(grid()));assertEquals("COMPLETE",result.layout().status());assertTrue(result.diagnostics().isEmpty());var cells=result.layout().tables().get(0).cells();assertEquals("合成甲",cells.get(2).text());assertEquals(List.of("b3"),cells.get(2).blockIds());assertEquals(List.of(cells.get(0).id()),cells.get(2).headerCellIds());assertNull(result.layout().textBoxes().get(0).confidence());assertEquals(.8,result.layout().textBoxes().get(1).confidence());var reverse=new ArrayList<>(grid().cells());Collections.reverse(reverse);assertEquals(result.layout().tables(),assembler.assemble(base(),text,List.of(new Grid("f",PIXEL_XYXY,2,2,reverse))).layout().tables());}
    @Test void explicitlyNormalizedCoordinatesConvertToTheSubmittedImageAndSameStableGrid(){var normalized=grid().cells().stream().map(c->new Region(c.row(),c.column(),c.rowSpan(),c.columnSpan(),List.of(c.box().get(0)*5,c.box().get(1)*10,c.box().get(2)*5,c.box().get(3)*10),c.header())).toList();var result=assembler.assemble(base(),text,List.of(new Grid("f",NORMALIZED_1000_XYXY,2,2,normalized)));assertTrue(result.diagnostics().isEmpty());assertEquals(assembler.assemble(base(),text,List.of(grid())).layout().tables(),result.layout().tables());}
    @Test void unknownCoordinateSpaceIsNeverGuessed(){var result=assembler.assemble(base(),text,List.of(new Grid("f","AUTO",2,2,grid().cells())));assertTrue(codes(result).contains("GRID_COORDINATE_SPACE_UNSUPPORTED"));assertEquals("PARTIAL",result.layout().status());assertEquals(base().textBoxes(),result.layout().textBoxes());assertTrue(result.layout().tables().isEmpty());}
    @Test void normalizedLookingValuesDeclaredPixelsAreRejectedInsteadOfRescaled(){var result=assembler.assemble(base(),text,List.of(new Grid("f",PIXEL_XYXY,1,1,List.of(cell(0,0,0,0,1000,1000,false)))));assertTrue(codes(result).contains("GRID_COORDINATES_OUT_OF_BOUNDS"));}
    @Test void unknownInputTextCoordinateSpaceFailsRatherThanBeingSilentlyReinterpreted(){var b=base();var unknown=new OcrLayout(b.schemaVersion(),b.status(),"UNKNOWN",b.frames(),b.textBoxes(),b.tables(),b.readingOrder(),b.warnings());assertThrows(IllegalArgumentException.class,()->assembler.assemble(unknown,text,List.of(grid())));}
    @Test void crossingTextBoxRejectsOnlyItsTableAndRetainsAllIndependentText(){var b=base();var boxes=new ArrayList<>(b.textBoxes());boxes.set(0,new TextBox("b1","f","姓名",new Box(90,10,20,10),null));var crossed=new OcrLayout(b.schemaVersion(),b.status(),b.coordinateSystem(),b.frames(),boxes,List.of(),b.readingOrder(),b.warnings());var result=assembler.assemble(crossed,text,List.of(grid()));assertTrue(codes(result).contains("GRID_TEXT_CROSSES_CELL_BOUNDARY"));assertEquals(boxes,result.layout().textBoxes());assertTrue(result.layout().tables().isEmpty());}
    @Test void logicallyDifferentButGeometricallyOverlappingCellsAreRejected(){var cells=new ArrayList<>(grid().cells());cells.set(0,cell(0,0,0,0,120,50,true));var result=assembler.assemble(base(),text,List.of(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(codes(result).contains("GRID_CELL_GEOMETRY_OVERLAP"));}
    @Test void duplicateLogicalCellsCannotCreateMultipleOwnership(){var cells=new ArrayList<>(grid().cells());cells.set(1,cell(0,0,100,0,200,50,true));var result=assembler.assemble(base(),text,List.of(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(codes(result).contains("GRID_LOGICAL_OVERLAP"));}
    @Test void missingLogicalCellsAreExplicitlyPartial(){var result=assembler.assemble(base(),text,List.of(new Grid("f",PIXEL_XYXY,2,2,grid().cells().subList(0,3))));assertTrue(codes(result).contains("GRID_LOGICAL_COVERAGE_INCOMPLETE"));assertEquals("PARTIAL",result.layout().status());}
    @Test void oneBadGridDoesNotEraseAnotherValidTable(){var left=new Grid("f",PIXEL_XYXY,2,1,List.of(cell(0,0,0,0,100,50,true),cell(1,0,0,50,100,100,false)));var bad=new Grid("f","UNSPECIFIED",2,1,List.of(cell(0,0,100,0,200,50,true),cell(1,0,100,50,200,100,false)));var result=assembler.assemble(base(),text,List.of(left,bad));assertEquals(1,result.layout().tables().size());assertEquals("合成甲",result.layout().tables().get(0).cells().get(1).text());assertEquals(4,result.layout().textBoxes().size());assertEquals("PARTIAL",result.layout().status());}
    @Test void overlappingTablesAreBothRejectedInsteadOfFirstWinning(){var result=assembler.assemble(base(),text,List.of(grid(),grid()));assertTrue(result.layout().tables().isEmpty());assertEquals(2,result.diagnostics().stream().filter(d->d.code().equals("GRID_TABLES_OVERLAP")).count());assertEquals(4,result.layout().textBoxes().size());}
    @Test void mergedCellsJoinOriginalBoxesInValidatedReadingOrder(){var merged=new Grid("f",PIXEL_XYXY,2,2,List.of(new Region(0,0,1,2,List.of(0d,0d,200d,50d),true),cell(1,0,0,50,100,100,false),cell(1,1,100,50,200,100,false)));var result=assembler.assemble(base(),text,List.of(merged));assertTrue(result.diagnostics().isEmpty());var cells=result.layout().tables().get(0).cells();assertEquals("姓名\n月份",cells.get(0).text());assertEquals(List.of("b1","b2"),cells.get(0).blockIds());assertEquals(List.of(cells.get(0).id()),cells.get(2).headerCellIds());}
    @Test void twoExactSourceLabelsCanIdentifyHeadersWithoutModelFlags(){var cells=grid().cells().stream().map(c->new Region(c.row(),c.column(),1,1,c.box(),false)).toList();var result=assembler.assemble(base(),text,List.of(new Grid("f",PIXEL_XYXY,2,2,cells)));var actual=result.layout().tables().get(0).cells();assertTrue(actual.get(0).header());assertTrue(actual.get(1).header());assertFalse(actual.get(2).header());assertEquals(List.of(actual.get(0).id()),actual.get(2).headerCellIds());}
    @Test void oneExactLabelDoesNotPromoteAnEntireRow(){var b=base();var boxes=new ArrayList<>(b.textBoxes());boxes.set(1,new TextBox("b2","f","备注内容",boxes.get(1).bbox(),null));var changed=new OcrLayout(b.schemaVersion(),b.status(),b.coordinateSystem(),b.frames(),boxes,List.of(),b.readingOrder(),List.of());var cells=grid().cells().stream().map(c->new Region(c.row(),c.column(),1,1,c.box(),false)).toList();var result=assembler.assemble(changed,text.replace("月份","备注内容"),List.of(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(result.layout().tables().get(0).cells().stream().noneMatch(Cell::header));}
    @Test void LabelSubstringsDoNotPromoteHeaders(){var b=base();var boxes=new ArrayList<>(b.textBoxes());boxes.set(0,new TextBox("b1","f","填写姓名",boxes.get(0).bbox(),null));boxes.set(1,new TextBox("b2","f","月份说明",boxes.get(1).bbox(),null));var changed=new OcrLayout(b.schemaVersion(),b.status(),b.coordinateSystem(),b.frames(),boxes,List.of(),b.readingOrder(),List.of());var cells=grid().cells().stream().map(c->new Region(c.row(),c.column(),1,1,c.box(),false)).toList();var result=assembler.assemble(changed,text.replace("姓名","填写姓名").replace("月份","月份说明"),List.of(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(result.layout().tables().get(0).cells().stream().noneMatch(Cell::header));}
    @Test void sameCoordinatesInAnotherFrameDoNotBorrowItsText(){var b=base();var other=new Frame("other",200,100,"b".repeat(64),"WORD_IMAGE",2,null,null,null);var multi=new OcrLayout(b.schemaVersion(),b.status(),b.coordinateSystem(),List.of(frame,other),b.textBoxes(),List.of(),b.readingOrder(),List.of());var result=assembler.assemble(multi,text,List.of(new Grid("other",PIXEL_XYXY,2,2,grid().cells())));assertTrue(codes(result).contains("GRID_WITHOUT_SOURCE_TEXT"));}
    @Test void invalidIndependentTranscriptionIsNeverRepairedByTheGrid(){assertThrows(IllegalArgumentException.class,()->assembler.assemble(base(),"姓名 月份 另一个人 2025-01",List.of(grid())));}
    @Test void inconsistentRowGeometryRetainsBoxesAndExplainsTheRejectedTable(){var cells=List.of(cell(1,0,0,0,100,50,false),cell(1,1,100,0,200,50,false),cell(0,0,0,50,100,100,true),cell(0,1,100,50,200,100,true));var result=assembler.assemble(base(),text,List.of(new Grid("f",PIXEL_XYXY,2,2,cells)));assertTrue(codes(result).contains("GRID_LAYOUT_VALIDATION_FAILED"));assertEquals(4,result.layout().textBoxes().size());}
}
